use super::*;
struct WorkProducer;
impl crate::OriginalWorkRecipient for WorkProducer{
 type Context<'turn,'source>=() where 'source:'turn;
 fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn source_turn<'turn,'source>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn admits<'reply,'turn,'source>(&mut self,_:&mut (),quote:crate::OriginalWorkQuote<'reply>,_:u64,_:u64)->crate::OriginalWorkQuoteComplete<'reply>where 'source:'turn{quote.complete(Ok(true))}
 fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut (),check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(context))}
 fn recover_partial<'reply,'turn,'source>(&mut self,context:&mut (),check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(context))}
}
fn with_effect<R>(grant:RetainedCloneGrant,maximum:u64,operation:impl FnOnce(&mut crate::RetainedAllocationEffect<'_>)->R)->(R,Option<usize>){
 use crate::OriginalWorkRecipient;let mut authority=crate::OriginalWorkAuthority::new(WorkProducer);let result=authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=crate::OriginalWork::empty();work.recipient=Some(&mut loan);let mut action=None;let mut proof=None;assert_eq!(work.prepare_for_action(maximum,&mut action).unwrap(),Some(true));let mut receipt=None;work.issue_performed_for_action(action,&mut receipt).unwrap();let mut actual=None;let output={let mut effect=crate::RetainedAllocationEffect::new(grant,maximum,&mut actual,receipt.as_mut().unwrap());operation(&mut effect)};let performed=crate::OriginalWorkSink::observed_work(receipt.as_ref().unwrap());work.claim_performed_for_action(action,&mut receipt).unwrap();if performed==0{work.cancel_for_action(&mut action).unwrap()}else{let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());let partial=partial.take().expect("original fixture Work partial outcome");assert_eq!(partial.total(),performed);assert!(partial.source_refusal().is_none());assert!(work.commit_for_action(performed,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()}(output,actual)}).unwrap();assert!(!authority.has_live_actions());result
}


fn post(bank:&mut RetainedCloneGrant,fuel:&mut u128,p:RetainedCloneProgress,work:u128){assert!(p.fits(*bank));assert!(work<=1);*fuel=fuel.checked_sub(work).unwrap();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;}
#[test]fn actual_ordered_shared_birth_null_and_release_keep_input_and_exact_work(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=u128::from(s["fuel"].as_u64().unwrap());let mut input=Some(row["value"].as_str().unwrap().to_owned());let pointer=input.as_ref().unwrap().as_ptr();let mut output=None;
 for grant in [RetainedCloneGrant{maximum_items:0,..bank},RetainedCloneGrant{maximum_capacity_bytes:SharedOwner::<String>::allocation_bytes()-1,..bank},RetainedCloneGrant{maximum_depth:0,..bank}]{let(turn,actual)=with_effect(grant,1,|effect|SharedOwner::admit_into(&mut input,&mut output,effect));assert_eq!(turn.work,u128::from(row["deniedWork"].as_u64().unwrap()));assert!(turn.result.unwrap().is_none());assert_eq!(actual,None);assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(output.is_none())}
 let(((turn,actual),attempts),heap)=crate::allocation_testing::observe_retirement_allocations(||crate::allocation_testing::refuse_one_allocation_on_this_thread(||with_effect(RetainedCloneGrant{maximum_items:1,..bank},1,|effect|SharedOwner::admit_into(&mut input,&mut output,effect))));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,u128::from(row["nullWork"].as_u64().unwrap()));assert!(turn.result.is_err());assert_eq!(actual,Some(0));fuel-=turn.work;assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(output.is_none());
 let((turn,actual),heap)=crate::allocation_testing::observe_retirement_allocations(||with_effect(RetainedCloneGrant{maximum_items:1,..bank},1,|effect|SharedOwner::admit_into(&mut input,&mut output,effect)));let p=turn.result.unwrap().unwrap();let mut owner=output.take().unwrap();assert!(input.is_none());assert_eq!(turn.work,u128::from(row["admitWork"].as_u64().unwrap()));assert_eq!(actual,Some(p.retained_capacity_bytes));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,turn.work);assert_eq!(owner.deref().as_ptr(),pointer);assert_eq!(serde_json::to_value(owner.deref()).unwrap(),row["value"]);
 let denied=owner.release_step(RetainedCloneGrant{maximum_items:0,..bank});assert_eq!(denied.work,u128::from(row["deniedWork"].as_u64().unwrap()));assert_eq!(denied.result.unwrap().progress,Default::default());assert_eq!(owner.deref().as_ptr(),pointer);let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||owner.release_step(RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,u128::from(row["releaseWork"].as_u64().unwrap()));let released=turn.result.unwrap();assert_eq!(heap,(released.progress.retained_capacity_bytes,released.progress.released_bytes));post(&mut bank,&mut fuel,released.progress,turn.work);assert!(owner.terminal_is_empty());assert_eq!(owner.release_step(Default::default()).work,u128::from(row["cachedWork"].as_u64().unwrap()));let mut close=crate::retirement::controlled::ControlledRetirement::new(released.value.unwrap()).map_err(|(error,_)|error).unwrap();
 for _ in 0..s["maximumTurns"].as_u64().unwrap(){if close.terminal_is_empty(){break}let grant=RetainedCloneGrant{maximum_items:1,..bank};let units=close.next_computational_work(grant.maximum_copy_bytes).unwrap();let(result,actual)=with_effect(grant,units,|effect|close.step(effect));let progress=result.unwrap().progress();let work=close.last_turn_work();if let Some(bytes)=actual{assert_eq!(bytes,progress.retained_capacity_bytes)}post(&mut bank,&mut fuel,progress,work)}assert!(close.terminal_is_empty());
}

#[test]
fn resident_shared_birth_keeps_original_slots_and_actual_marker(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();assert_eq!(fixture["birthFields"],serde_json::json!(["sourceOption","payload","strongCounter","weakCounter","destinationOption"]));let value=fixture["stock"]["items"].as_u64().unwrap();let mut input=Some(value);let mut output=None;let demand=SharedOwner::<u64>::admission_demand(&input,&output).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:0,maximum_depth:demand.depth};assert_eq!(SharedOwner::<u64>::admission_work(&input,&output).unwrap(),1);
 for denied in [RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..grant},RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(turn,actual)=with_effect(denied,1,|effect|SharedOwner::admit_into(&mut input,&mut output,effect));assert!(turn.result.unwrap().is_none());assert_eq!(turn.work,0);assert_eq!(actual,None);assert_eq!(input,Some(value));assert!(output.is_none())}
 let(((turn,actual),attempts),heap)=crate::allocation_testing::observe_retirement_allocations(||crate::allocation_testing::refuse_one_allocation_on_this_thread(||with_effect(grant,1,|effect|SharedOwner::admit_into(&mut input,&mut output,effect))));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert!(turn.result.is_err());assert_eq!(turn.work,1);assert_eq!(actual,Some(0));assert_eq!(input,Some(value));assert!(output.is_none());
 let((turn,actual),heap)=crate::allocation_testing::observe_retirement_allocations(||with_effect(grant,1,|effect|SharedOwner::admit_into(&mut input,&mut output,effect)));let progress=turn.result.unwrap().unwrap();assert_eq!(turn.work,1);assert_eq!(actual,Some(demand.capacity_bytes));assert_eq!(heap,(progress.retained_capacity_bytes,0));assert_eq!(progress.retained_capacity_bytes,demand.capacity_bytes);assert_eq!(progress.copied_bytes,demand.copy_bytes);assert!(input.is_none());let mut owner=output.take().unwrap();assert_eq!(*owner,value);let turn=owner.release_step(RetainedCloneGrant{maximum_items:1,maximum_release_bytes:demand.capacity_bytes,maximum_depth:1,..Default::default()});let released=turn.result.unwrap();assert_eq!(released.value,Some(value));assert_eq!(released.progress.released_bytes,demand.capacity_bytes);assert!(owner.terminal_is_empty());
}
